function EnvioEmailModel() {
    var self = this;

    this.idModal = ko.observable();

    this.destinatarioSelecao = ko.observable();
    this.destinatarioDigitado = ko.observable();

    this.assunto = ko.observable();
    this.corpoEmail = ko.observable();
    this.emails = ko.observableArray([]);

    this.openModal = ko.observable(false);

    this.openModal.subscribe(function (newValue) {
        if (newValue) {
            self.showModal();
        } else
            self.closeModal();
    });
    this.exibirDestinatario = ko.observable(false);
    this.caregarDestinatarios = ko.observable(false);
    this.reloadEmails = ko.observable(true);

    this.codigoEntidade = ko.observable();
    this.tipoEntidade = ko.observable();

    this.destinatario = function () {

        if (self.caregarDestinatarios()) {
            if (self.emails().length > 0) {
                return self.destinatarioSelecao();
            } else {
                return self.destinatarioDigitado();
            }
        }

        return "";
    };

    this.validacao = ko.validatedObservable({
        destinatarioSelecao: self.destinatarioSelecao,
        destinatarioDigitado: self.destinatarioDigitado,
        assunto: self.assunto,
        corpoEmail: self.corpoEmail,
    });

    this.getIdModal = function () {
        return "#{0}".format(self.idModal())
    }

    this.limpar = function () {
        self.destinatarioSelecao(null);
        self.destinatarioDigitado(null);
        self.corpoEmail(null);
    }

    this.init = function () {

        if (self.caregarDestinatarios() === true) {
            if (IsUndefinedOrNullOrEmpty(self.codigoEntidade()) || IsUndefinedOrNullOrEmpty(self.tipoEntidade())) {
                console.error("As informações da entidade não foi informada");
                return;
            }
        }

        self.getEmailEntidade();
    }

    this.showModal = function () {
        self.init();
        self.limpar();
        $(self.getIdModal()).modal({ backdrop: 'static', keyboard: false });
    }

    this.closeModal = function () {
        $(self.getIdModal()).modal("hide");
        self.limpar();
    }

    this.sendEmail = function () {
        if (!self.validacao.isValid()) return;

        self.onSend(self.getModel(), self.closeModal);
    }

    this.onSend = function (model, callback) {
        facil.noty.error('Erro', 'Método onSend não implementado para o componete de envio de E-mail.', true);
    }

    this.getEmailEntidade = function () {

        if (self.caregarDestinatarios()) {
            facil.exibirLoading(true);
            var model =
            {
                Codigo: ko.utils.unwrapObservable(self.codigoEntidade),
                TipoEntidade: ko.utils.unwrapObservable(self.tipoEntidade)
            }

            get("LookUp/GetEmailEntidade", cryptography(model), true).done(function (data) {
                var itens = [];
                facil.exibirLoading(false);
                if (data.HasError) { facil.noty.error('Erro', data.Message, true); return; }
                if (data.Data != "") {
                    ko.utils.arrayForEach(data.Data, function (item) {
                        itens.push(item);
                    });
                }
                self.emails(itens);
            }).fail(function (xhr, textStatus, errorThrown) {
                facil.exibirLoading(false);
                facil.noty.error('Erro', 'Ocorreram falhas na pesquisa.', true);
            });

        }
    }

    this.getModel = function () {
        var model =
        {
            Destinatario: self.destinatario(),
            Assunto: ko.utils.unwrapObservable(self.assunto),
            CorpoEmail: ko.utils.unwrapObservable(self.corpoEmail),
        };

        return model;
    }

}
;
