ko.components.register('lista-multi', {
    viewModel: function (params) {
        var self = this;
        this.select = params.select;

        if (!params.select && !params.value) {
            console.error("Informe o parâmetro select do tipo InputListMulti ou o value do tipo  ko.observable");
            return;
        }

        if (self.select) {
            if (ko.isObservable(self.select)) {
                self.select = self.select();
            }

            if (self.select.constructor !== InputListMulti.prototype.constructor) {
                console.error("A propriedade select deve ser do tipo InputListMulti");
                return;
            }
        } else {
            self.select = new InputListMulti();
        }

        if (params.value) {
            if (!ko.isObservable(params.value)) {
                console.error("A propriedade value deve ser do tipo ko.observable");
                return;
            }
        }

        self.select.tabIndex = createProp(params.tabIndex, self.select.tabIndex);
        self.select.name = createProp(params.name, self.select.name);
        self.select.label = createProp(params.label, self.select.label);
        self.select.isVisible = createProp(params.visible, self.select.isVisible);
        self.select.labelVisible = createProp(params.labelVisible, self.select.labelVisible);
        self.select.obrigatorio = createProp(params.required, self.select.obrigatorio);
        setProp(params.renderIdOption, self.select.renderIdOption);
        setProp(params.labelVisible, self.select.labelVisible);
        self.select.readOnly = createProp(params.readOnly, self.select.readOnly);
        setProp(params.textError, self.select.textError);
        setProp(params.optionsText, self.select.optionsText);
        setProp(params.optionsValue, self.select.optionsValue);
        setProp(params.placeholder, self.select.placeholder);
        self.select.classTitle = createProp(params.classTitle, self.select.classTitle);
        if (IsUndefinedOrNullOrEmpty(self.select.classTitle()))
            self.select.title = createProp(params.title, self.select.title);
        else
            self.select.titleIco = createProp(params.title, self.select.title);
        var itensSubscribe = null;
        var valueSubscribe = null;
        if (params.itens) {
            if (ko.isObservable(params.itens)) {
                self.select.itens = params.itens;
                if (itensSubscribe != null)
                    itensSubscribe.dispose();

                itensSubscribe = self.select.itens.subscribe(function (newValue) {
                    if (newValue) {
                        var result = ko.utils.arrayFilter(newValue, function (item) { return facil.getPropertieObject(item, self.select.optionsValue()) == self.select.codigo(); });
                        if (result.length == 0)
                            self.select.limpar();
                    }

                    self.select.setupLookup();
                });
            }
            else {
                var itens = [];
                ko.utils.arrayForEach(params.itens, function (item) {
                    itens.push(item);
                });
                self.select.itens(itens);
            }
        }

        if (params.onChange) {
            if (ko.isObservable(params.onChange)) {
                console.error("A propriedade onChange não pode ser um Observable.");
                return;
            }

            if (typeof params.onChange !== 'function') {
                console.error("A propriedade onChange deve ser uma função");
                return;
            }
            else
                params.onChange = params.onChange.bind(this);

            self.select.onChange = params.onChange;
        }

        if (params.value) {

            self.select.codigo = createProp(params.value, self.select.codigo);

            self.select.onChangeInternal = function () {
                if (params.value() != self.select.codigo())
                    params.value(self.select.codigo());
            }

            if (!IsUndefinedOrNullOrEmpty(params.value())) {
                self.select.codigo(params.value());
            }

            if (valueSubscribe != null)
                valueSubscribe.dispose();

            valueSubscribe = params.value.subscribe(function (value) {                

                if (IsUndefinedOrNullOrEmpty(value))
                    self.select.limpar();
                else 
                    self.select.initSelectedItem();
            });

            params.value.extend({
                required: {
                    params: self.select.label(),
                    message: self.select.textError(),
                    onlyIf: function () {
                        return self.select.obrigatorio() && self.select.isVisible() && !self.select.readOnly();
                    }
                }
            });

        }

        self.select.idElement(createGuid());
        self.select.init();
        self.select.initSubscribe();

        if (ko.isObservable(params.size))
            params.size = params.size();

        var size = params.size || 6;
        var sizeXs = params.sizeXs || 12;
        var sizeLg = params.sizeLg || size;
        if (!params.inLine)
            this.classCss = ko.observable('col-md-{0} col-xs-{1} col-lg-{2}'.format(size, sizeXs, sizeLg));
        else
            this.classCss = "";
    },
    template: component.templates.selectizeMulti
});;
