        //Verificar o tipo
        var obj = Object.getPrototypeOf(self.input)
        if (self.input) {
            if (ko.isObservable(self.input)) {
                console.error("A propriedade input não pode ser um Observable.");
                return;
            }

            var obj = Object.getPrototypeOf(self.input)
            if (obj.constructor.name !== "InputBeneficiario") {
                console.error("A propriedade input deve ser do tipo InputBeneficiario");
                return;
            }
        } else {
            console.error("A propriedade input deve ser informada e ser do tipo InputBeneficiario");
            return;
        }

        setProp(params.somenteAtivos, self.input.somenteAtivos);
        setProp(params.somenteTitular, self.input.somenteTitular);
