(function () {
    var Contrast = {
        storage: 'contrastState',
        cssClass: 'contrast',
        currentState: null,
        check: checkContrast,
        getState: getContrastState,
        setState: setContrastState,
        toogle: toogleContrast,
        updateView: updateViewContrast
    };

    window.toggleContrast = function () { Contrast.toogle(); };

    Contrast.check();

    function checkContrast() {
        this.updateView();
    }

    function getContrastState() {
        return localStorage.getItem(this.storage) === 'true';
    }

    function setContrastState(state) {
        localStorage.setItem(this.storage, '' + state);
        this.currentState = state;
        this.updateView();
    }

    function updateViewContrast() {
        var body = document.body;

        if (!body) return;

        if (this.currentState === null)
            this.currentState = this.getState();

        if (this.currentState)
            body.classList.add(this.cssClass);
        else
            body.classList.remove(this.cssClass);
    }

    function toogleContrast() {
        this.setState(!this.currentState);
    }
})();;
(function () {

    var clockAtendimento = undefined;

    function DadosAtentimento() {
        var self = this;

        this.icon = ko.observable();
        this.nome = ko.observable();
        this.title = ko.observable();

        this.init = function (data) {
            self.icon("");
            if (data.Nome.indexOf(data.Id) > -1)
                self.nome(data.Nome);
            else
                self.nome("({0}) - {1}".format(data.Id, data.Nome));

            var tipoAcesso = parseInt(data.TipoDeAcesso);
            switch (tipoAcesso) {
                case tiposAcesso.Beneficiario:
                    self.icon("fa-user");
                    self.title("Beneficiário");
                    break;
                case tiposAcesso.Medico:
                    self.icon("fa-user-md");
                    self.title("Médico");
                    break;
                case tiposAcesso.Hospital:
                    self.icon("fa-hospital-o");
                    self.title("Hospital");
                    break;
                case tiposAcesso.Laboratorio:
                    self.icon("fa-medkit");
                    self.title("Laboratório");
                    break;
            }
        }
    }

    function AtendimentoViewModel() {
        var self = this;
        this.tipoDeAcesso = ko.observable();
        this.tempoExpiracao = ko.observable(0);
        this.dadosAtendimento = new DadosAtentimento();

        this.emAtedimento = ko.observable(false);
        this.exibirEntidadeAtendimento = ko.observable(false);
        this.onChangeTipoDeAcesso = function () {
            self.entidadeAtendimento.setValues("", "")
            self.entidadeAtendimento.limpar(true);
            self.exibirEntidadeAtendimento(false);

            var action = "";
            var qtdCaracterPesquisa = 3;
            var tipoAcesso = parseInt(self.tipoDeAcesso());
            switch (tipoAcesso) {
                case tiposAcesso.Beneficiario:
                    action = component.ActionsFind.ConstBeneficiario;
                    break;
                case tiposAcesso.Medico:
                    action = component.ActionsFind.ConstMedico;
                    break;
                case tiposAcesso.Hospital:
                    action = component.ActionsFind.ConstHospital;
                    break;
                case tiposAcesso.Laboratorio:
                    action = component.ActionsFind.ConstLaboratorio;
                    break;
            }

            if (action) {                
                self.entidadeAtendimento.action(action);
                self.entidadeAtendimento.label(tiposAcesso.getDescricao(tipoAcesso) + ":");
                self.entidadeAtendimento.qtdCaracterPesquisa(qtdCaracterPesquisa);
                self.exibirEntidadeAtendimento(true);
            }
        }
        this.tiposDeAcesso = ko.observableArray([]);
        this.entidadeAtendimento = new InputSelectize();

        this.validacaoAtendimento = ko.validatedObservable({
            entidadeAtendimento: self.entidadeAtendimento.codigo,
            tipoDeAcesso: self.tipoDeAcesso
        });

        this.openModalAtendimento = function () {
            self.limpar();
            $("#modal-atendimento").modal({ backdrop: 'static', keyboard: false });
        }

        this.iniciarAtendimento = function () {
            if (!self.validacaoAtendimento.isValid()) return;

            var model =
            {
                Id: self.entidadeAtendimento.codigo(),
                Nome: self.entidadeAtendimento.nome(),
                TipoDeAcesso: self.tipoDeAcesso(),
                DadosExtras: self.entidadeAtendimento.dadosExtras()
            };

            self.dadosAtendimento.init(model);
            window.localStorage.removeItem(facil.constants.dadosPerfilAtendimento);
            window.localStorage.setItem(facil.constants.dadosPerfilAtendimento, JSON.stringify(model));
            window.localStorage.removeItem(facil.constants.TempoEmAtendimento)

            //Fechar o modal
            $("#modal-atendimento").modal("hide");
            location.reload();
            self.initClock();
        }

        this.finalizarAtendimento = function () {

            facil.noty.confirm('Atendimento', 'Deseja realmente finalizar o atendimento?', true, [{
                addClass: 'btn btn-primary btn-sm', text: 'Sim', onClick: function ($noty) {
                    $noty.close();
                    self.finalizarInterno();
                }
            }, {
                addClass: 'btn btn-danger btn-sm', text: 'Não', onClick: function ($noty) {
                    $noty.close();
                }
            }]);
        }

        this.tempoFinalizado = function () {

            facil.noty.confirm('Atendimento', 'O tempo programado do atentimento finalizou!', true, [{
                addClass: 'btn btn-primary btn-sm', text: 'Reiniciar tempo', onClick: function ($noty) {
                    $noty.close();
                    window.localStorage.setItem(facil.constants.TempoEmAtendimento, self.tempoExpiracao())
                    clockAtendimento.setTime(self.tempoExpiracao());
                    clockAtendimento.start();
                }
            }, {
                addClass: 'btn btn-danger btn-sm', text: 'Finalizar atendimento', onClick: function ($noty) {
                    $noty.close();
                    self.finalizarInterno();
                }
            }]);
        }

        this.finalizarInterno = function () {
            try {
                window.localStorage.removeItem(facil.constants.dadosPerfilAtendimento);
                window.localStorage.removeItem(facil.constants.TempoEmAtendimento);
                self.emAtedimento(false);
                self.limpar();
                if (clockAtendimento != null)
                    clockAtendimento.stop();
            } catch (e) { }
        }

        this.limpar = function () {
            self.tipoDeAcesso(null);
            self.entidadeAtendimento.limpar(true);
        }

        this.init = function (usuario) {
            self.tiposDeAcesso.push({ Id: tiposAcesso.Beneficiario, Descricao: tiposAcesso.getDescricao(tiposAcesso.Beneficiario) });
            self.tiposDeAcesso.push({ Id: tiposAcesso.Medico, Descricao: tiposAcesso.getDescricao(tiposAcesso.Medico) });
            self.tiposDeAcesso.push({ Id: tiposAcesso.Hospital, Descricao: tiposAcesso.getDescricao(tiposAcesso.Hospital) });
            self.tiposDeAcesso.push({ Id: tiposAcesso.Laboratorio, Descricao: tiposAcesso.getDescricao(tiposAcesso.Laboratorio) });

            if (usuario.TipoDeAcesso != tiposAcesso.Atendente) {
                self.finalizarInterno();
            } else {
                var dados = window.localStorage.getItem(facil.constants.dadosPerfilAtendimento);
                if (dados) {
                    self.emAtedimento(true);
                    self.dadosAtendimento.init(JSON.parse(dados));
                    self.initClock();
                } else {
                    self.finalizarInterno();
                }                
            }   
        }

        this.initClock = function () {
            var timer = window.localStorage.getItem(facil.constants.TempoEmAtendimento);
            if (timer <= 0)
                timer = self.tempoExpiracao();

            clockAtendimento = $('.timer-atendimento').FlipClock(timer, {
                countdown: true,
                language: 'pt-br',
            });
            clockAtendimento.face.decrement = function () {
                if (clockAtendimento.time.getTimeSeconds() == 0) {
                    clockAtendimento.stop();
                    self.tempoFinalizado();
                    window.localStorage.removeItem(facil.constants.TempoEmAtendimento);
                }
                else {
                    clockAtendimento.time.subSecond();
                    window.localStorage.setItem(facil.constants.TempoEmAtendimento, clockAtendimento.time.getTimeSeconds())
                }
            }
            clockAtendimento.start();
        }

        this.getTempoAtendimento = function () {
            var timer = window.localStorage.getItem(facil.constants.TempoMaximoAtendimento);
            if (IsUndefinedOrNullOrEmpty(timer)) {
                getWithoutParam("Settings/GetTempoAtendimento", true).done(function (data) {
                    var valor = 0;
                    if (!data.HasError) {
                        valor = parseInt(data.Data);
                    }
                    self.tempoExpiracao(valor * 60);
                    window.localStorage.setItem(facil.constants.TempoMaximoAtendimento, self.tempoExpiracao());
                }).fail(function () {
                    self.tempoExpiracao(0);
                    window.localStorage.setItem(facil.constants.TempoMaximoAtendimento, 0);
                });
            } else {
                self.tempoExpiracao(parseInt(timer));
            }
        }
    }

    $(document).ready(function () {
        if ($("#usuario-logado").val()) {
            var viewModel = new AtendimentoViewModel();
            facil.ko.initValidation();
            viewModel.getTempoAtendimento();
            var usuario = JSON.parse($("#usuario-logado").val());
            viewModel.init(usuario);
            ko.applyBindings(viewModel, document.getElementById("menu-atendimento"));
        }
    });
})();;
function TermoConsentimentoRepository() {
    var self = this;

    self.pesquisar = function (param) {
        return $.ajax({
            type: "POST",
            url: basePath.concat("TermoConsentimento/Pesquisar"),
            data: JSON.stringify(param),
            dataType: "json",
            contentType: 'application/json',
            async: true,
            error: function (xhr, status, error) {
                alert(xhr.responseText);
            }
        });
    };
    self.desativar = function (param) {
        return $.ajax({
            type: "POST",
            url: basePath.concat("TermoConsentimento/Desativar"),
            data: JSON.stringify(param),
            dataType: "json",
            contentType: 'application/json',
            async: true,
            error: function (xhr, status, error) {
                alert(xhr.responseText);
            }
        });
    };
    self.solicitarConsentimento = function (param) {
        return $.ajax({
            type: "POST",
            url: basePath.concat("TermoConsentimento/SolicitarConsentimento"),
            data: JSON.stringify(param),
            dataType: "json",
            contentType: 'application/json',
            async: true,
            error: function (xhr, status, error) {
                alert(xhr.responseText);
            }
        });
    };
    self.salvarTermo = function (model) {
        return $.ajax({
            type: "POST",
            url: basePath + "TermoConsentimento/SalvarTermo",
            data: JSON.stringify(model),
            cache: false,
            contentType: "application/json;charset=utf-8"
        });
    };
    self.viewReportAceite = function (param) {
        facil.exibirLoading(true);
        return $.ajax({
            type: "POST",
            dataType: "json",
            async: true,
            contentType: "application/json",
            url: basePath.concat("TermoConsentimento/ViewReportAceite"),
            data: JSON.stringify(param),
            cache: false,
            success: function (data) {
                facil.exibirLoading(false);
                const blob = new Blob([base64ToArrayBuffer(data.file)], { type: data.type });
                const file = new File([blob], data.name, { type: data.type });
                const url = URL.createObjectURL(file);
                window.open(url);
            },
            error: function (xhr, status, error) {
                facil.exibirLoading(false);
                facil.noty.warning('Atenção!', xhr.responseText, true);
            }
        });

    };
    self.getTermoUsuario = function () {

        return $.ajax({
            type: "GET",
            url: basePath + "TermoConsentimento/GetTermoUsuario",
            cache: false,
            dataType: "json",
            contentType: "application/json"
        });
    };
    self.darAceite = function () {
        return $.ajax({
            type: "GET",
            url: basePath + "TermoConsentimento/DarAceite",
            cache: false,
            dataType: "json",
            contentType: "application/json"
        });
    };
    self.fecharModalAceite = function () {
        return $.ajax({
            type: "GET",
            url: basePath + "TermoConsentimento/FecharModalAceite",
            cache: false,
            dataType: "json",
            contentType: "application/json"
        });
    };
    self.getTermo = function (param) {
        return $.ajax({
            type: "POST",
            url: basePath.concat("TermoConsentimento/GetTermo"),
            data: JSON.stringify(param),
            dataType: "json",
            contentType: 'application/json',
            async: true,
            error: function (xhr, status, error) {
                alert(xhr.responseText);
            }
        });
    };
    self.getInfoAceiteTermoAtivo = function () {
        return getWithoutParam("TermoConsentimento/GetInfoAceiteTermoAtivo");
    };
};
$(document).ready(function () {
    var repository = new TermoConsentimentoRepository();

    $("#lnk-termo-aceite").click(function () {
        repository.getInfoAceiteTermoAtivo().done(function (data) {
            iterateSelector('.loadingOverlay', function (value) { value.style.display = 'none'; });

            if (data.HasError) {
                facil.noty.error('Erro', data.Message, true);
            }
            else {
                if (data.Data) {
                    facil.noty.confirm('Termo de Consentimento', data.Data, true, [{
                        addClass: 'btn btn-primary btn-sm', text: 'OK', onClick: function ($noty) {
                            $noty.close();
                        }
                    }]);
                }
            }

        }).fail(function (xhr, textStatus, errorThrown) {
            facil.noty.error('Erro', 'Ocorreu algum problema ao recuperar as informações do aceite ao termo de consentimento!', true);
            iterateSelector('.loadingOverlay', function (value) { value.style.display = 'none'; });
        });
    })

});;
